                        ? "rgba(255,100,100,0.18)"
                        : "rgba(255,255,255,0.06)",
                    borderRadius: 7,
                  }}
                />
              ))}
            </div>

            {/* Stats row */}
            <div
              style={{
                display: "flex",
                gap: 60,
                marginTop: 52,
                opacity: statsP,
                transform: `translateY(${interpolate(statsP, [0, 1], [20, 0])}px)`,
              }}
            >
              {[
                { val: "47K", label: "Views" },
                { val: "2.8K", label: "Comments" },
                { val: "12K", label: "Shares" },
              ].map((s, i) => (
                <div key={i} style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                  <span style={{ fontSize: 56, fontWeight: 800, color: COLORS.accent }}>
                    {s.val}
                  </span>
                  <span
                    style={{
                      fontSize: 30,
                      fontWeight: 400,
                      color: "rgba(255,255,255,0.3)",
                      letterSpacing: "0.12em",
                      textTransform: "uppercase",
                    }}
                  >
                    {s.label}
                  </span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

